'use client';
import { useState } from 'react'; import { toast } from 'sonner';
export function FileUpload({endpoint,field,accept,label}:{endpoint:string;field:string;accept:string;label:string}){const [loading,setLoading]=useState(false); async function upload(e:React.FormEvent<HTMLFormElement>){e.preventDefault(); const fd=new FormData(e.currentTarget); setLoading(true); const r=await fetch(endpoint,{method:'POST',body:fd}); const j=await r.json(); setLoading(false); if(!r.ok) toast.error(j.error); else toast.success('Upload completed successfully');} return <form onSubmit={upload} className="glass mt-6 max-w-xl rounded-3xl p-6 shadow"><input name={field} type="file" accept={accept} required className="w-full rounded-2xl border bg-white p-3"/><button className="mt-4 rounded-2xl bg-blue-700 px-6 py-3 font-semibold text-white" disabled={loading}>{loading?'Uploading...':label}</button></form>}
